import re,sys
def blocks(path):
    L=open(path).read().split('\n'); out={}; name=None; buf=[]
    kw=re.compile(r'^(?:@\[[^\]]*\]\s*)?(def|abbrev|structure|inductive|instance|theorem|example|class)\s*(\S*)')
    top=re.compile(r'^(/--|/-!|--|section|end\b|namespace|open|set_option|#|$)')
    def flush():
        if name: out.setdefault(name,[]).append('\n'.join(buf).rstrip())
    for l in L:
        m=kw.match(l)
        if m:
            flush(); kind,n=m.group(1),m.group(2)
            name=(kind+' '+n) if kind in('def','abbrev','structure','inductive','class') else None
            buf=[l]
        elif top.match(l):
            flush(); name=None; buf=[]
        else:
            buf.append(l)
    flush(); return out
a=blocks(sys.argv[1]); b=blocks(sys.argv[2])
for n in sorted(set(a)|set(b)):
    if n not in b: print('REMOVED',n)
    elif n not in a: print('ADDED',n)
    elif a[n]!=b[n]: print('CHANGED',n)
EOF
